int read_line(char * buf, int size) {
  if (!isatty(STDIN_FILENO))   {
    if (!fgets(buf, size, stdin))     return 0;
    int len = (int)strlen(buf);
    while (((len > 0) && (buf[(len - 1)] == '\n' || buf[(len - 1)] == '\r')))     buf[--len] = '\x00';
    return len;
  }
  struct termios old, raw;
  tcgetattr(STDIN_FILENO, &old);
  raw = old;
  (raw.c_lflag &= ~(ECHO | ICANON));
  raw.c_cc[VMIN] = 1;
  raw.c_cc[VTIME] = 0;
  tcsetattr(STDIN_FILENO, TCSANOW, &raw);
  int pos = 0, len = 0;
  while ((len < (size - 1)))   {
    char c;
    if ((read(STDIN_FILENO, &c, 1) <= 0))     break;
    if (c == '\x1B')     {
      char seq[2];
      if ((read(STDIN_FILENO, &seq[0], 1) <= 0))       break;
      if ((read(STDIN_FILENO, &seq[1], 1) <= 0))       break;
      if (seq[0] == '[')       {
        if ((seq[1] == 'D' && (pos > 0)))         {
          (pos)--;
          printf("\033[D");
          fflush(stdout);
        }
        else         if ((seq[1] == 'C' && (pos < len)))         {
          (pos)++;
          printf("\033[C");
          fflush(stdout);
        }
      }
      continue;
    }
    if ((c == '\n' || c == '\r'))     {
      buf[len] = '\x00';
      break;
    }
    if ((c == '\x08' || c == 127))     {
      if ((pos > 0))       {
        memmove(&buf[(pos - 1)], &buf[pos], (len - pos));
        (len)--;
        (pos)--;
        printf("\b%s ", &buf[pos]);
        for (int i = len;
(i > pos); (i)--)         printf("\b");
        fflush(stdout);
      }
      continue;
    }
    if ((pos < len))     memmove(&buf[(pos + 1)], &buf[pos], (len - pos));
    buf[pos] = c;
    (len)++;
    (pos)++;
    putchar(c);
    if ((pos < len))     {
      printf("%s", &buf[pos]);
      for (int i = len;
(i > pos); (i)--)       printf("\b");
    }
    fflush(stdout);
  }
  putchar('\n');
  tcsetattr(STDIN_FILENO, TCSANOW, &old);
  return len;
}

void skip_ws(const char * * p) {
  while ((**p && ((unsigned char)**p <= 32)))   (*p)++;
}

int parse_hex4(const char * * p) {
  int val = 0;
  for (int i = 0;
(i < 4); (i)++)   {
    char c = *(*p)++;
    if (((c >= '0') && (c <= '9')))     val = ((val << 4) | (c - '0'));
    else     if (((c >= 'a') && (c <= 'f')))     val = ((val << 4) | ((c - 'a') + 10));
    else     if (((c >= 'A') && (c <= 'F')))     val = ((val << 4) | ((c - 'A') + 10));
    else     return -1;
  }
  return val;
}

char * parse_raw_string(const char * * p) {
  if (**p != '\"')   return NULL;
  (*p)++;
  int cap = 64, len = 0;
  char * buf = (char *)malloc(cap);
  while (**p)   {
    char c = **p;
    if (c == '\"')     {
      (*p)++;
      break;
    }
    if (c == '\\')     {
      (*p)++;
      switch (**p)       {
        case '\"':
          buf[(len)++] = '\"';
        break;
        case '\\':
          buf[(len)++] = '\\';
        break;
        case '/':
          buf[(len)++] = '/';
        break;
        case 'b':
          buf[(len)++] = '\x08';
        break;
        case 'f':
          buf[(len)++] = '\x0C';
        break;
        case 'n':
          buf[(len)++] = '\n';
        break;
        case 'r':
          buf[(len)++] = '\r';
        break;
        case 't':
          buf[(len)++] = '\t';
        break;
        case 'u':
          {
            (*p)++;
            int cp = parse_hex4(p);
            if ((cp < 0))             {
              free(buf);
              return NULL;
            }
            if ((cp <= 127))             buf[(len)++] = (char)cp;
            else             if ((cp <= 2047))             {
              buf[(len)++] = (char)(192 | (cp >> 6));
              buf[(len)++] = (char)(128 | (cp & 63));
            }
            else             {
              buf[(len)++] = (char)(224 | (cp >> 12));
              buf[(len)++] = (char)(128 | ((cp >> 6) & 63));
              buf[(len)++] = (char)(128 | (cp & 63));
            }
            continue;
          }
        default:
          buf[(len)++] = **p;
        break;
      }
    }
    else     {
      buf[(len)++] = c;
    }
    (*p)++;
    if ((len >= (cap - 4)))     {
      (cap *= 2);
      buf = (char *)realloc(buf, cap);
    }
  }
  buf[len] = '\x00';
  return buf;
}

