  if (strcmp(name, "type") == 0)   return __nopa_sel_cmdType_;
  if (strcmp(name, "len") == 0)   return __nopa_sel_cmdLen;
  if (strcmp(name, "new") == 0)   return __nopa_sel_cmdNew;
  if (strcmp(name, "parse") == 0)   return __nopa_sel_cmdParse_;
